QString handoff(const QJsonObject& p){return "冻结材料包身份："+p.value("id").toString()+"\n主题身份："+p.value("scope").toObject().value("id").toString()+"\n可返回 sector-research-return-v1 JSON，字段 packetId、scopeId、report、candidates；身份只证明手工回填对应包，不证明事实。\n"+p.value("prompt").toString();}
void freshSelected(){int found=0;for(auto v:scopes?scopes():QJsonArray{}){auto s=v.toObject();if(sectorResearch::scopeKey(s)==sectorResearch::scopeKey(selected)){++found;business::require(s==selected,"主题来源已变化；请刷新并重新选择");}}business::require(found==1,"主题已缺失或身份重复");}
