QWidget* sectorResearchPage(std::shared_ptr<BusinessStore>b,QWidget*p,SectorResearchScopeProvider s,SectorResearchInstrumentProvider i,SourceHandoffOpener o,SectorResearchInstrumentAction a){return new Page(b,p,s,i,o,a);}
bool sectorResearchBack(QWidget*w){auto p=dynamic_cast<Page*>(w);if(!p||!p->ai)return false;if(p->relation)p->closeRelation();else p->closeAi();return true;}
bool sectorResearchSelectScope(QWidget*w,const QString&kind,const QString&id){auto p=dynamic_cast<Page*>(w);return p&&p->select(kind,id);}









void sectorResearchSetAiPreferences(QWidget*w,std::function<QJsonObject()> prefs){auto p=dynamic_cast<Page*>(w);if(p)p->aiPreferences=prefs;}


